import { Injectable } from "@nestjs/common";
import {
  IValidationStrategy,
  ValidationReport,
  RawQuestion,
} from "../interfaces/validation-strategy.interface";
import {
  GenerationContext,
  DatasetData,
} from "../interfaces/generation-context.interface";

/**
 * DatasetValidator
 *
 * Validates questions generated by the DATASET strategy.
 * Checks: passage consistency, answer derivable from passage, reading level.
 */
@Injectable()
export class DatasetValidator implements IValidationStrategy {
  async validate(
    context: GenerationContext,
    question: RawQuestion,
  ): Promise<ValidationReport> {
    const errors: string[] = [];
    const warnings: string[] = [];
    const payload = context.payload as DatasetData;

    // 1. Question text must not be empty
    if (!question.questionText?.trim()) {
      errors.push("Question text is empty.");
    }

    // 2. Must have exactly 4 options
    if (!question.options || question.options.length !== 4) {
      errors.push(`Expected 4 options, got ${question.options?.length ?? 0}.`);
    }

    // 3. Correct answer must be one of A/B/C/D
    const validAnswers = ["A", "B", "C", "D"];
    if (!validAnswers.includes(question.correctAnswer?.toUpperCase())) {
      errors.push(
        `Correct answer "${question.correctAnswer}" is not a valid option (A/B/C/D).`,
      );
    }

    // 4. Passage must exist
    if (!payload.passage?.trim()) {
      errors.push(
        "Dataset passage is empty — cannot generate reading comprehension question.",
      );
    }

    // 5. Basic passage consistency: question should reference the passage topic
    const passageLower = payload.passage?.toLowerCase() ?? "";
    const questionLower = question.questionText?.toLowerCase() ?? "";
    const passageWords = passageLower
      .split(/\s+/)
      .filter((w: string) => w.length > 4)
      .slice(0, 20);
    const hasRelevantTerms = passageWords.some((word: string) =>
      questionLower.includes(word),
    );
    if (!hasRelevantTerms && payload.passage?.trim()) {
      warnings.push(
        "Question text may not be directly related to the passage content.",
      );
    }

    // 6. Explanation must reference the passage
    if (!question.explanation?.trim()) {
      warnings.push("Explanation is empty — it should cite the passage.");
    }

    // 7. Passage length check (reading level proxy)
    const wordCount = payload.passage?.split(/\s+/).length ?? 0;
    if (wordCount < 20) {
      warnings.push(
        `Passage is very short (${wordCount} words). Consider a longer passage for reading comprehension.`,
      );
    }

    return { valid: errors.length === 0, errors, warnings };
  }
}
